// The admin console's alert screens (docs/49): rules, channels (webhook and email), incidents
// and the evaluator banner, against the plain gateway on the database e2e/console_server.py
// seeded for this run, with the suite's test SMTP server beside it. The passwords, the webhook
// token and the recipient's tag were generated by playwright.config.ts at the start of the run.
//
// The seed's key of app-one expires in 3 days, so the default rule "Key expires within 14 days"
// fires on the evaluator's first cycle: the incident these tests read and acknowledge.

import {
  expect,
  test,
  type APIRequestContext,
  type Locator,
  type Page,
  type TestInfo,
} from "@playwright/test";
import { picturedAndChecked } from "./a11y";

test.describe.configure({ mode: "serial" });

function secret(name: string): string {
  const value = process.env[name];
  if (value === undefined || value === "") {
    throw new Error(`${name} is not set: run the console tests through playwright.config.ts`);
  }
  return value;
}

interface Account {
  username: string;
  first: () => string;
  password: () => string;
}

function account(username: string, variable: string): Account {
  return {
    username,
    first: () => secret(`CONSOLE_E2E_${variable}_FIRST_PASSWORD`),
    password: () => secret(`CONSOLE_E2E_${variable}_PASSWORD`),
  };
}

const ADMIN = account("admin-e2e", "ADMIN");
const VIEWER = account("viewer-e2e", "VIEWER");
const APP_ADMIN = account("appadmin-e2e", "APPADMIN");

const ORG = "/v1/admin/orgs/acme";
const HOOK_ORIGIN = "https://hooks.example.com";
const hookToken = () => secret("CONSOLE_E2E_HOOK_TOKEN");
const hookUrl = () => `${HOOK_ORIGIN}/services/${hookToken()}`;
const recipient = () => `oncall-${secret("CONSOLE_E2E_RECIPIENT_TAG")}@example.com`;
const second = () => `second-${secret("CONSOLE_E2E_RECIPIENT_TAG")}@example.com`;
const MAILBOX = () => `http://127.0.0.1:${secret("CONSOLE_E2E_MAIL_PORT")}/messages`;

// Values the gateway made during the run (signing keys, confirmation codes): none may be
// visible in a screenshot either.
const madeInRun: string[] = [];

// Every secret this run generated: none may be visible in a screenshot.
const PLANTED = [
  "CONSOLE_E2E_PEPPER",
  "CONSOLE_E2E_VAULT_KEY",
  "CONSOLE_E2E_OPERATOR_PASSWORD",
  "CONSOLE_E2E_HOOK_TOKEN",
  ...["ADMIN", "VIEWER", "APPADMIN"].flatMap((who) => [
    `CONSOLE_E2E_${who}_FIRST_PASSWORD`,
    `CONSOLE_E2E_${who}_PASSWORD`,
  ]),
];

async function shownText(page: Page): Promise<string> {
  return page.evaluate(
    () =>
      document.body.innerText +
      Array.from(
        document.querySelectorAll("input, textarea"),
        (field) => (field as HTMLInputElement).value,
      ).join(" "),
  );
}

/** The planted and made-in-run secrets found in what the page shows: its text and fields. */
async function visibleSecrets(page: Page): Promise<string[]> {
  const shown = await shownText(page);
  return [
    ...PLANTED.filter((name) => shown.includes(secret(name))),
    ...madeInRun.filter((value) => shown.includes(value)).map(() => "a value made in the run"),
  ];
}

/**
 * A screenshot for the PR (in the run's output folder, git-ignored; copied to
 * docs/pr-c2-screenshots/ by hand), taken only once no secret of the run is visible.
 */
/** The page's toasts (docs/54): where a change's result is said. */
function toasts(page: Page) {
  return page.locator(".toasts");
}

async function picture(page: Page, testInfo: TestInfo, name: string): Promise<void> {
  expect(await visibleSecrets(page)).toEqual([]);
  // In both themes, each checked by axe in both (docs/53).
  await picturedAndChecked(page, testInfo, name);
}

/** Logs in; an account still on its first password (this file run alone) changes it first. */
async function logIn(page: Page, who: Account): Promise<void> {
  await page.goto("/dashboard/");
  const form = page.getByRole("region", { name: "Log in", exact: true });
  await form.getByLabel("Username").fill(who.username);
  await form.getByLabel("Password", { exact: true }).fill(who.password());
  await form.getByRole("button", { name: "Log in" }).click();
  const loggedIn = page.getByRole("button", { name: /^Account:/ });
  const refused = form.getByRole("alert");
  await expect(loggedIn.or(refused)).toBeVisible();
  if (await loggedIn.isVisible()) return;
  await form.getByLabel("Password", { exact: true }).fill(who.first());
  await form.getByRole("button", { name: "Log in" }).click();
  const change = page.getByRole("region", { name: "Change your password", exact: true });
  await change.getByLabel("Current password", { exact: true }).fill(who.first());
  await change.getByLabel("New password", { exact: true }).fill(who.password());
  await change.getByRole("button", { name: "Change password" }).click();
  await expect(loggedIn).toBeVisible();
}

async function open(page: Page, section: string): Promise<void> {
  // The page's navigation (Home repeats some of its links).
  await page
    .getByRole("navigation", { name: "Sections", exact: true })
    .getByRole("link", { name: section, exact: true })
    .click();
  await expect(page.getByRole("heading", { name: section, level: 2 })).toBeVisible();
}

/**
 * An application's tab (docs/56), opened by its address as a link does: the rules and an
 * application's incidents are tabs of its page now, no longer a section with a dropdown.
 */
async function openTab(
  page: Page,
  applicationId: string,
  tab: "rules" | "incidents",
): Promise<void> {
  await page.evaluate((hash) => {
    window.location.hash = hash;
  }, `#/app/${applicationId}/${tab}`);
  await expect(
    page
      .getByRole("navigation", { name: "Application sections" })
      .getByRole("link", { name: tab === "rules" ? "Alert rules" : "Incidents", exact: true }),
  ).toHaveAttribute("aria-current", "page");
}

function row(region: Locator, name: string | RegExp): Locator {
  return region
    .getByRole("row")
    .filter({ has: region.page().getByRole("rowheader", { name, exact: true }) });
}

async function stepUp(page: Page, who: Account): Promise<void> {
  const dialog = page.getByRole("dialog", { name: "Confirm with your password" });
  await dialog.getByLabel("Password", { exact: true }).fill(who.password());
  await dialog.getByRole("button", { name: "Confirm" }).click();
  await expect(page.getByRole("dialog")).toHaveCount(0);
}

/** The code mailed to `address`, read from the test SMTP server's mailbox (never the browser). */
async function mailedCode(request: APIRequestContext, address: string, nth = 1): Promise<string> {
  let codes: string[] = [];
  await expect
    .poll(async () => {
      const answer = await request.get(MAILBOX());
      const messages = (await answer.json()) as { to: string[]; text: string; tls: boolean }[];
      codes = messages
        .filter((m) => m.to.includes(address) && m.tls)
        .flatMap((m) => /Confirmation code: ([A-Z2-7]{5}-[A-Z2-7]{5})/.exec(m.text)?.[1] ?? []);
      return codes.length;
    })
    .toBeGreaterThanOrEqual(nth);
  // As the mail shows it (two groups of five), and as typed: the gateway takes either.
  const code = codes[nth - 1] ?? "";
  madeInRun.push(code, code.replace("-", ""));
  return code;
}

async function mailCount(request: APIRequestContext, address: string): Promise<number> {
  const messages = (await (await request.get(MAILBOX())).json()) as { to: string[] }[];
  return messages.filter((m) => m.to.includes(address)).length;
}

/** Waits until the evaluator has made the seed's incident fire: a state, never a time. */
async function firingIncident(page: Page): Promise<void> {
  await expect
    .poll(
      async () => {
        const answer = await page.request.get(
          `${ORG}/applications/app-one/incidents?state=firing&limit=100`,
        );
        if (!answer.ok()) return 0;
        return ((await answer.json()) as { incidents: unknown[] }).incidents.length;
      },
      { timeout: 150_000 },
    )
    .toBeGreaterThan(0);
}

/** The buttons and fields that change something, inside the screen (not the header). */
async function writeControls(page: Page): Promise<number> {
  const main = page.getByRole("main");
  const buttons = main.getByRole("button", {
    name: /^(Edit |Copy |Disable|Enable|Delete|Restore|Save rule|Create channel|Test send|Remove |Send the code|Confirm|Add|Acknowledge)/,
  });
  const fields = main.getByRole("textbox");
  return (await buttons.count()) + (await fields.count());
}

test("every alert page shows the evaluator banner while /healthz says stale or unknown, and none when ok", async ({
  page,
}) => {
  test.setTimeout(150_000);
  await logIn(page, ADMIN);
  // The gateway's own answer: ok, so no banner.
  await expect
    .poll(
      async () =>
        ((await (await page.request.get("/healthz")).json()) as { alert_evaluator: string })
          .alert_evaluator,
    )
    .toBe("ok");
  for (const section of ["Channels", "Incidents"]) {
    await open(page, section);
    await expect(page.getByRole("main").getByRole("heading", { level: 2 })).toHaveText(section);
    await expect(page.getByRole("alert", { name: "Alert evaluation" })).toHaveCount(0);
  }
  await openTab(page, "app-one", "rules");
  await expect(page.getByRole("alert", { name: "Alert evaluation" })).toHaveCount(0);
  // The other states, as the gateway would answer them.
  for (const [state, shown] of [
    ["stale", "stale"],
    ["unknown", "unknown"],
    ["not a state", "unreadable"],
  ] as const) {
    await page.route("**/healthz", (route) =>
      route.fulfill({ json: { status: "ok", alert_evaluator: state } }),
    );
    for (const section of ["Channels", "Incidents"]) {
      await page.goto("/dashboard/console.html#/organization");
      await open(page, section);
      await expect(page.getByRole("alert", { name: "Alert evaluation" })).toContainText(
        `Alert evaluation: ${shown}.`,
      );
    }
    await page.goto("/dashboard/console.html#/organization");
    await openTab(page, "app-one", "rules");
    await expect(page.getByRole("alert", { name: "Alert evaluation" })).toContainText(
      `Alert evaluation: ${shown}.`,
    );
    await page.unroute("**/healthz");
  }
  // /healthz not answering at all: shown as unreadable, never hidden.
  await page.route("**/healthz", (route) => route.abort());
  await page.goto("/dashboard/console.html#/organization");
  await open(page, "Incidents");
  await expect(page.getByRole("alert", { name: "Alert evaluation" })).toContainText("unreadable");
  await page.unroute("**/healthz");
  // Not on the settings screens, which are not alert pages.
  await open(page, "Organization settings");
  await expect(page.getByRole("alert", { name: "Alert evaluation" })).toHaveCount(0);
});

test("alert rules: state and last value, defaults marked, the checked editor with its preview, enable, delete, restore", async ({
  page,
}, testInfo) => {
  test.setTimeout(180_000);
  await logIn(page, ADMIN);
  await firingIncident(page);
  await openTab(page, "app-one", "rules");
  const rules = page.getByRole("region", { name: "Rules", exact: true });
  await expect(page.getByText("May change")).toBeVisible();
  const expiring = row(rules, "Key expires within 14 days");
  await expect(expiring).toContainText("firing");
  await expect(expiring).toContainText("default");
  await expect(row(rules, "Error rate above 5 percent")).toContainText("too few to judge");
  await expect(row(rules, "Answered by a hosted provider")).toContainText("disabled");

  // An edit, checked by the gateway at each change, with the last hour's preview.
  await rules.getByRole("button", { name: "Edit Error rate above 5 percent" }).click();
  const editor = page.getByRole("region", { name: "Rule editor", exact: true });
  const check = page.getByRole("status", { name: "Rule check" });
  await expect(check).toContainText("Valid.");
  await expect(check).toContainText("Over the last hour the condition never held.");
  await expect(check).toContainText("minutes had too few requests to judge");
  await editor.getByLabel("threshold: value").fill("abc");
  await expect(check).toContainText("Not JSON: threshold.");
  await expect(editor.getByRole("button", { name: "Save rule" })).toBeDisabled();
  await editor.getByLabel("threshold: value").fill("1000");
  await expect(check).toContainText("Refused (threshold)");
  await expect(editor.getByRole("button", { name: "Save rule" })).toBeDisabled();
  await editor.getByLabel("threshold: value").fill("7");
  await expect(check).toContainText("Valid.");
  await editor.getByRole("button", { name: "Save rule" }).click();
  await expect(page.getByText("Saved Error rate above 5 percent as version 2.")).toBeVisible();
  await expect(row(rules, "Error rate above 5 percent")).toContainText("default, changed");
  await expect(row(rules, "Error rate above 5 percent")).toContainText("> 7 over 5 min");

  // A copy is a new rule; disabling and deleting it are versions like any other.
  await rules.getByRole("button", { name: "Copy Requests rate limited" }).click();
  await expect(check).toContainText("Valid.");
  await page.getByRole("button", { name: "Save rule" }).click();
  await expect(page.getByText("Created Copy of Requests rate limited.")).toBeVisible();
  const copy = row(rules, "Copy of Requests rate limited");
  await expect(copy).toContainText("disabled");
  await copy.getByRole("button", { name: "Enable Copy of Requests rate limited" }).click();
  await expect(page.getByText("Enabled Copy of Requests rate limited.")).toBeVisible();
  await expect(copy).toContainText("not firing");
  await picture(page, testInfo, "alert-rules-admin");
  await copy.getByRole("button", { name: "Delete Copy of Requests rate limited" }).click();
  await expect(page.getByText("Deleted Copy of Requests rate limited.")).toBeVisible();
  await expect(row(rules, "Copy of Requests rate limited")).toHaveCount(0);

  // Restore the defaults: the changed default is back as it was.
  await rules.getByRole("button", { name: "Restore default rules" }).click();
  await expect(page.getByText("Restored the default rules.")).toBeVisible();
  await expect(row(rules, "Error rate above 5 percent")).toContainText("> 5 over 5 min");
});

test("channels: a webhook shows only its origin and its key once; an email channel's recipient verified with the mailed code; test send; disable and delete", async ({
  page,
}, testInfo) => {
  test.setTimeout(150_000);
  await logIn(page, ADMIN);
  await open(page, "Channels");
  const list = page.getByRole("region", { name: "Channel list", exact: true });
  await expect(list).toContainText("The organization has no channel.");

  // A webhook: the step-up asked for, the key shown once, the URL never shown again.
  const create = page.getByRole("region", { name: "New channel", exact: true });
  await create.getByLabel("Name").fill("Ops hook");
  await create.getByLabel("Webhook URL").fill(hookUrl());
  await create.getByRole("button", { name: "Create channel" }).click();
  await stepUp(page, ADMIN);
  const key = page.getByRole("region", { name: "Signing key", exact: true });
  await expect(key).toContainText("shown once");
  const signingKey = (await key.locator("code").textContent()) ?? "";
  madeInRun.push(signingKey);
  expect(signingKey.length).toBeGreaterThan(20);
  await expect(create.getByLabel("Name")).toHaveValue("");
  await expect(row(list, "Ops hook")).toContainText(HOOK_ORIGIN);
  expect(await shownText(page)).not.toContain(hookToken());
  await key.getByRole("button", { name: "I have stored it" }).click();
  await expect(key).toHaveCount(0);
  expect(await shownText(page)).not.toContain(signingKey);

  // An email channel: its recipient unverified until the mailed code is entered.
  await create.getByLabel("Type").selectOption("email");
  await create.getByLabel("Name").fill("On call");
  await create.getByLabel("Recipients (one address a line)").fill(recipient());
  await create.getByLabel("An organization default").check();
  await create.getByRole("button", { name: "Create channel" }).click();
  await stepUp(page, ADMIN);
  await expect(
    page.getByText("Created On call. Each recipient's confirmation: delivered."),
  ).toBeVisible();
  await expect(row(list, "On call")).toContainText("1 recipient, 0 verified");
  await picture(page, testInfo, "channels-admin");

  await list.getByRole("button", { name: "Open On call" }).click();
  const channel = page.getByRole("region", { name: "Channel", exact: true });
  const recipients = channel.getByRole("table", { name: "Recipients" });
  await expect(row(recipients, recipient())).toContainText("unverified");
  const code = await mailedCode(page.request, recipient());
  // A wrong code: refused, in the gateway's words, and the field emptied.
  const field = channel.getByLabel(`Code for ${recipient()}`);
  await field.fill(code === "AAAAA-AAAAA" ? "BBBBB-BBBBB" : "AAAAA-AAAAA");
  await channel.getByRole("button", { name: "Confirm" }).click();
  await expect(channel.getByRole("alert")).toContainText("not valid");
  await expect(field).toHaveValue("");
  await field.fill(code);
  await channel.getByRole("button", { name: "Confirm" }).click();
  await expect(toasts(page).getByText(`${recipient()} is verified.`)).toBeVisible();
  await expect(row(recipients, recipient())).toContainText("verified");

  // A second recipient: added with a step-up, sent its code again, then removed.
  await channel.getByLabel("Add a recipient").fill(second());
  await channel.getByRole("button", { name: "Add", exact: true }).click();
  await stepUp(page, ADMIN);
  await expect(row(recipients, second())).toContainText("unverified");
  await mailedCode(page.request, second());
  await channel.getByRole("button", { name: `Send the code again to ${second()}` }).click();
  await expect(toasts(page).getByText("Code sent again: delivered.")).toBeVisible();
  await mailedCode(page.request, second(), 2);
  await channel.getByRole("button", { name: `Remove ${second()}` }).click();
  await expect(toasts(page).getByText(`Removed ${second()}.`)).toBeVisible();
  await expect(row(recipients, second())).toHaveCount(0);

  // Test send: to the verified recipient only, and its outcome shown.
  const before = await mailCount(page.request, recipient());
  await channel.getByRole("button", { name: "Test send" }).click();
  await expect(toasts(page).getByText("Test send: delivered.")).toBeVisible();
  expect(await mailCount(page.request, recipient())).toBe(before + 1);
  await expect(channel).toContainText("Deliveries");
  await picture(page, testInfo, "channel-email-admin");

  // The webhook: disabled, then deleted.
  await channel.getByRole("button", { name: "Back to the list" }).click();
  await list.getByRole("button", { name: "Open Ops hook" }).click();
  await expect(channel).toContainText(HOOK_ORIGIN);
  await channel.getByRole("button", { name: "Disable" }).click();
  await expect(toasts(page).getByText("Disabled.")).toBeVisible();
  await channel.getByRole("button", { name: "Delete", exact: true }).click();
  await channel.getByRole("button", { name: "Delete it" }).click();
  await expect(page.getByText("Deleted Ops hook.")).toBeVisible();
  await expect(row(list, "Ops hook")).toHaveCount(0);
});

test("a viewer sees every alert page with no write control, no channel and no recipient address", async ({
  page,
}, testInfo) => {
  test.setTimeout(150_000);
  const lines: string[] = [];
  page.on("console", (message) => lines.push(message.text()));
  await logIn(page, VIEWER);
  await openTab(page, "app-one", "rules");
  await expect(page.getByText("Read only")).toBeVisible();
  await expect(
    row(page.getByRole("region", { name: "Rules", exact: true }), "Key expires within 14 days"),
  ).toBeVisible();
  expect(await writeControls(page)).toBe(0);
  await picture(page, testInfo, "alert-rules-viewer");

  // Channels: not among a viewer's places (the gateway's capabilities answer), and opening the
  // address draws no channel screen, only one sentence where it lands: its organization's
  // Applications (docs/50, docs/51).
  await expect(
    page
      .getByRole("navigation", { name: "Sections", exact: true })
      .getByRole("link", { name: "Channels" }),
  ).toHaveCount(0);
  await page.goto("/dashboard/#/channels");
  await expect(
    page.getByRole("region", { name: "Applications", exact: true }).getByRole("alert").first(),
  ).toHaveText("That page is not available to this account.");
  expect(await writeControls(page)).toBe(0);
  await picture(page, testInfo, "channels-viewer");

  await open(page, "Incidents");
  const incidents = page.getByRole("region", { name: "Incidents", exact: true });
  // Still firing (the admin acknowledges it later): Acknowledge would be offered if allowed.
  await expect(row(incidents, "Key expires within 14 days")).toContainText("firing");
  await picture(page, testInfo, "incidents-viewer");
  await incidents.getByRole("button", { name: "Open Key expires within 14 days" }).click();
  const incident = page.getByRole("region", { name: "Incident", exact: true });
  await expect(incident.getByRole("list", { name: "Timeline" })).toContainText("Opened");
  await expect(incident).toContainText("firing");
  expect(await writeControls(page)).toBe(0);
  await picture(page, testInfo, "incident-viewer");

  // No recipient address anywhere a viewer can see, nor in the browser's console.
  for (const address of [recipient(), second()]) {
    expect(await page.content()).not.toContain(address);
    expect(lines.join("\n")).not.toContain(address);
  }
});

test("an application's own admin changes its rules and reads its incidents, but no channel", async ({
  page,
}) => {
  await logIn(page, APP_ADMIN);
  // Its one application's page is where it lands (docs/56); the rules are a tab of it.
  await openTab(page, "app-one", "rules");
  await expect(page.getByText("May change")).toBeVisible();
  await expect(page.getByRole("button", { name: "Restore default rules" })).toBeVisible();

  // Its application's incidents are this account's to read, on the same page.
  await openTab(page, "app-one", "incidents");
  await expect(
    row(page.getByRole("region", { name: "Incidents", exact: true }), "Key expires within 14 days"),
  ).toBeVisible();
  // The organization's list is not: its address draws the landing's sentence, and asks nothing.
  const asked: string[] = [];
  page.on("request", (request) => asked.push(request.url()));
  await page.goto("/dashboard/console.html#/incidents");
  await expect(
    page.getByRole("region", { name: "App one", exact: true }).getByRole("alert").first(),
  ).toHaveText("That page is not available to this account.");
  expect(asked.filter((url) => /\/orgs\/[^/]+\/incidents/.test(url))).toEqual([]);

  // Channels are not among its places, and their address draws only that sentence (docs/50).
  await expect(
    page
      .getByRole("navigation", { name: "Sections", exact: true })
      .getByRole("link", { name: "Channels" }),
  ).toHaveCount(0);
  await page.goto("/dashboard/#/channels");
  await expect(
    page.getByRole("region", { name: "App one", exact: true }).getByRole("alert").first(),
  ).toHaveText("That page is not available to this account.");
});

test("incidents: the organization's list, an incident's timeline and notifications, and Acknowledge", async ({
  page,
}, testInfo) => {
  test.setTimeout(180_000);
  await logIn(page, ADMIN);
  await firingIncident(page);
  await open(page, "Incidents");
  const incidents = page.getByRole("region", { name: "Incidents", exact: true });
  await expect(row(incidents, "Key expires within 14 days")).toContainText("firing");
  await expect(row(incidents, "Key expires within 14 days")).toContainText("app-one");
  await picture(page, testInfo, "incidents-admin");
  await incidents.getByRole("button", { name: "Open Key expires within 14 days" }).click();
  const incident = page.getByRole("region", { name: "Incident", exact: true });
  await expect(incident.getByRole("heading", { name: "Key expires within 14 days" })).toBeVisible();
  const timeline = incident.getByRole("list", { name: "Timeline" });
  await expect(timeline).toContainText("Opened");
  await expect(timeline).toContainText("Fired");
  await expect(incident.getByRole("table", { name: "Notifications" })).toContainText("firing");
  await picture(page, testInfo, "incident-admin");
  await incident.getByRole("button", { name: "Acknowledge" }).click();
  await expect(toasts(page).getByText("Acknowledged.")).toBeVisible();
  await expect(timeline).toContainText("Acknowledged by");
  await expect(incident.getByRole("button", { name: "Acknowledge" })).toHaveCount(0);
  // The list, filtered by state, as the gateway filters it.
  await incident.getByRole("button", { name: "Back to the list" }).click();
  // The states are tabs now (docs/55): the same states, the same query to the gateway.
  await page.getByRole("tab", { name: "acknowledged", exact: true }).click();
  await expect(row(incidents, "Key expires within 14 days")).toContainText("acknowledged");
  await page.getByRole("tab", { name: "pending", exact: true }).click();
  await expect(incidents).toContainText("No incident.");
});

test("leak scan: no webhook URL, signing key, confirmation code or recipient address kept in storage, the page, the URL or the console", async ({
  page,
}) => {
  test.setTimeout(150_000);
  const sent: string[] = [];
  const answered: string[] = [];
  const lines: string[] = [];
  page.on("request", (request) => sent.push(request.postData() ?? ""));
  page.on("response", (response) => {
    if (response.request().method() !== "GET" && response.url().includes("/alert-channels")) {
      void response.text().then((text) => answered.push(text));
    }
  });
  page.on("console", (message) => lines.push(message.text()));

  const token = `${hookToken()}-scan`;
  const url = `${HOOK_ORIGIN}/services/${token}`;
  const address = `scan-${secret("CONSOLE_E2E_RECIPIENT_TAG")}@example.com`;
  await logIn(page, ADMIN);
  await open(page, "Channels");
  const create = page.getByRole("region", { name: "New channel", exact: true });
  await create.getByLabel("Name").fill("Scan hook");
  await create.getByLabel("Webhook URL").fill(url);
  await create.getByRole("button", { name: "Create channel" }).click();
  await stepUp(page, ADMIN);
  const key = page.getByRole("region", { name: "Signing key", exact: true });
  const signingKey = (await key.locator("code").textContent()) ?? "";
  await key.getByRole("button", { name: "I have stored it" }).click();

  await create.getByLabel("Type").selectOption("email");
  await create.getByLabel("Name").fill("Scan mail");
  await create.getByLabel("Recipients (one address a line)").fill(address);
  await create.getByRole("button", { name: "Create channel" }).click();
  await stepUp(page, ADMIN);
  const list = page.getByRole("region", { name: "Channel list", exact: true });
  await list.getByRole("button", { name: "Open Scan mail" }).click();
  const channel = page.getByRole("region", { name: "Channel", exact: true });
  const code = await mailedCode(page.request, address);
  await channel.getByLabel(`Code for ${address}`).fill(code);
  await channel.getByRole("button", { name: "Confirm" }).click();
  await expect(toasts(page).getByText(`${address} is verified.`)).toBeVisible();

  // The controls: each planted value is found where it must be, so the scan can see them.
  expect(sent.some((body) => body.includes(token))).toBe(true);
  expect(answered.some((body) => body.includes(signingKey))).toBe(true);
  expect(signingKey.length).toBeGreaterThan(20);
  expect(sent.some((body) => body.includes(code))).toBe(true);
  const bare = code.replace("-", "");
  expect(bare).toHaveLength(10);
  expect(await page.content()).toContain(address); // the admin's own view lists it

  const kept = await page.evaluate(async () => {
    const dump = (storage: Storage) =>
      Array.from({ length: storage.length }, (_, i) => {
        const k = storage.key(i) ?? "";
        return `${k}=${storage.getItem(k) ?? ""}`;
      }).join("\n");
    const databases = await indexedDB.databases();
    return {
      local: dump(localStorage),
      session: dump(sessionStorage),
      cookie: document.cookie,
      fields: Array.from(
        document.querySelectorAll("input, textarea"),
        (field) => (field as HTMLInputElement).value,
      ).join("\n"),
      databases: databases.map((d) => d.name ?? "").join("\n"),
    };
  });
  const places = {
    ...kept,
    page: await page.content(),
    url: page.url(),
    console: lines.join("\n"),
  };
  for (const [place, text] of Object.entries(places)) {
    expect(text.includes(token), `webhook URL in ${place}`).toBe(false);
    expect(text.includes(signingKey), `signing key in ${place}`).toBe(false);
    expect(text.includes(code), `confirmation code in ${place}`).toBe(false);
    expect(text.includes(bare), `confirmation code (bare) in ${place}`).toBe(false);
    if (place !== "page") expect(text.includes(address), `address in ${place}`).toBe(false);
  }
  expect(kept.cookie).toBe("");
  expect(kept.session).toBe("");
  expect(kept.local === "" || kept.local.startsWith("gateway-dashboard-theme=")).toBe(true);
});
